INSERT INTO `_tb_seed_help` (`name`, `template_text`, `text`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
('help:main', 'TortoiseBots: owned companions and the living world.\nWhisper help <topic> to search. Shift-click a topic link into a whisper to open it.\n[h:help:owned|Owned bots] [h:help:party|Party controls] [h:help:combat|Combat] [h:help:travel|Travel]\n[h:help:equipment|Equipment] [h:help:quests|Quests] [h:help:recovery|Recovery] [h:help:classes|Classes]\n[h:help:random|Random population] [h:help:admin|Administration] [h:help:strategies|Strategies]', '', '', '', '', '', '', '', '', ''),
('help:search', 'Matching topics:\n<found>', '', '', '', '', '', '', '', '', ''),
('help:owned', 'Use .bot roster to see your characters. Use .bot add <Name> to log in an owned character as a bot.\nUse .bot invite <Name> to invite it, and .bot remove <Name> to log it out with native saving.\nYour real client login reclaims your character. Commands enforce ownership and the server command permissions.\nUse .bot status <Name> to inspect its current state.', '', '', '', '', '', '', '', '', ''),
('help:party', 'Use .bot follow, .bot stay, .bot guard or .bot free to control your companions.\n.bot summon [Name] requests a safe summon out of combat; native teleport restrictions still apply.\n.bot formation arrow|queue|near|line|circle|shield changes the follow formation.\n.bot ready checks readiness. .bot action ready starts a group ready check.', '', '', '', '', '', '', '', '', ''),
('help:combat', 'Select an enemy and use .bot action attack. Use .bot action stop to stop attacks.\n.bot action interrupt chooses an eligible interrupt. .bot action cc <mark> controls the marked enemy.\n.bot action focus skull coordinates focus fire; .bot action aoe off helps protect crowd control.\n.bot action pull and .bot action pullback use the party tank\'s existing pull strategy.\nThe bot still checks range, spell availability, cooldowns and native combat restrictions.', '', '', '', '', '', '', '', '', ''),
('help:travel', 'Bots use native ground paths, flight masters, mounts and transport handling.\nWhisper taxi <destination> near a flight master, or home near an innkeeper to set a home bind.\nFollow your party leader with .bot follow. Use .bot summon [Name] for a safe owner-requested recovery.\nA rejected route is retried through movement logic; an unavailable path is not permission to walk through terrain.', '', '', '', '', '', '', '', '', ''),
('help:equipment', 'Whisper items to list inventory, equip <item> to equip, unequip <slot> to remove equipment, or use <item> to use it.\nAt a vendor, whisper sell gray or buy <item>; use repair near an appropriate repair NPC.\nWhisper trainer near a class trainer to learn available abilities through native purchases.\nWhisper talents or spells to inspect learned capabilities. Item links can be used in commands.', '', '', '', '', '', '', '', '', ''),
('help:quests', 'Whisper quests to inspect your log and accept to accept an offered quest.\nUse talk to interact with an NPC, reward [choice] to choose a quest reward, and share to share eligible quests.\nQuest prerequisites, objectives, offered gossip choices and reward restrictions remain native server rules.', '', '', '', '', '', '', '', '', ''),
('help:recovery', 'After death, whisper release to release spirit, corpse run to return to your corpse, or revive for the spirit-healer path.\nWhisper reset to reset AI action/strategy state. It is different from resetting persistent random-population data.\nUse .bot status <Name> and .bot summon [Name] to inspect or recover an owned companion when permitted.', '', '', '', '', '', '', '', '', ''),
('help:strategies', 'Strategies select triggers and actions for combat, noncombat and dead states.\nThe co, nc and dead whisper commands inspect or change the corresponding strategy sets.\nUse +name to add and -name to remove a strategy. Available strategies depend on class and build.\nUse direct .bot action commands for party tactics; these still use the existing action engine.', '', '', '', '', '', '', '', '', ''),
('help:classes', 'Nine Vanilla classes are supported. Role suitability depends on talents, learned spells and equipment.\n[h:class:warrior|Warrior] [h:class:paladin|Paladin] [h:class:hunter|Hunter]\n[h:class:rogue|Rogue] [h:class:priest|Priest] [h:class:shaman|Shaman]\n[h:class:mage|Mage] [h:class:warlock|Warlock] [h:class:druid|Druid]', '', '', '', '', '', '', '', '', ''),
('help:random', 'Random bots come from the configured random-account pool. Admission, creation and maintenance run through the native headless lifecycle.\nAutologin, automatic character creation, battleground participation and LFT fill are separately configured.\nOwned companions are excluded from random maintenance. A human master or party can also restrict autonomous activities.\nUse .bot lease status to inspect activity leases; administrator population commands are listed under [h:help:admin|Administration].', '', '', '', '', '', '', '', '', ''),
('help:admin', 'Administrator commands use normal server permissions, including console and authenticated SOAP.\nrndbot stats reports population; rndbot update requests reconciliation.\nrndbot refresh|upgrade|revive|change_strategy|remove <name-prefix|all> queues bounded work for live random bots.\nahbot status|reload|rebuild [all]|item <id> manages the selected auction controller.\nperfmon toggle|reset|tick|stack|map controls optional profiling. Unsupported commands report an error.', '', '', '', '', '', '', '', '', ''),
('class:warrior', 'Protection tank or Arms/Fury melee damage. Stances, taunts and interrupts depend on learned abilities.', '', '', '', '', '', '', '', '', ''),
('class:paladin', 'Holy healing, Protection tanking or Retribution melee damage. Blessings, auras and Turtle Holy Strike follow the selected spec.', '', '', '', '', '', '', '', '', ''),
('class:hunter', 'Ranged or Survival melee damage with pet support. Pet management, traps and Turtle melee abilities depend on learned spells.', '', '', '', '', '', '', '', '', ''),
('class:rogue', 'Melee damage with stealth, poisons, Sap and Kick where available. Crowd control still requires a valid target.', '', '', '', '', '', '', '', '', ''),
('class:priest', 'Discipline/Holy healing or Shadow damage. Healing, dispels and Shackle use class and target restrictions.', '', '', '', '', '', '', '', '', ''),
('class:shaman', 'Restoration healing, Enhancement melee or Elemental ranged damage. Totems and Earth Shock follow the active strategies.', '', '', '', '', '', '', '', '', ''),
('class:mage', 'Arcane, Fire or Frost ranged damage. Polymorph, Counterspell and mana recovery use native spell checks.', '', '', '', '', '', '', '', '', ''),
('class:warlock', 'Affliction, Demonology or Destruction ranged damage with demons. DoTs, pet control and crowd control depend on learned spells.', '', '', '', '', '', '', '', '', ''),
('class:druid', 'Bear tank, Cat melee, Restoration healer or Balance ranged damage. Form selection and spell availability follow the active role.', '', '', '', '', '', '', '', '', '');
INSERT INTO `ai_playerbot_help_texts` (`name`, `template_text`, `text`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) SELECT s.`name`, s.`template_text`, s.`text`, s.`text_loc1`, s.`text_loc2`, s.`text_loc3`, s.`text_loc4`, s.`text_loc5`, s.`text_loc6`, s.`text_loc7`, s.`text_loc8` FROM `_tb_seed_help` s
